package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var stdin []string

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		stdin = append(stdin, scanner.Text())
	}
	run()
}

func run() {
	// write code here:
	m, _ := strconv.ParseFloat(strings.TrimSpace(stdin[0]), 64)
	n := 1.0
	for i := 1.0; i <= m; i++ {
		n += 4 * (i - 1)
	}
	fmt.Println(strconv.FormatFloat(n, 'f', -1, 64))
}
